<?php
require 'config.php';require 'includes/functions.php';need_login();verify();
if(user()['role']==='patient'&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['cancel'])){$q=$pdo->prepare("UPDATE appointments SET status='cancelled' WHERE id=? AND patient_id=? AND status IN ('pending','confirmed') AND appointment_date>=CURDATE()");$q->execute([(int)$_POST['cancel'],user()['id']]);flash($q->rowCount()?'Appointment cancelled.':'Unable to cancel this appointment.',$q->rowCount()?'success':'error');go('dashboard.php');}
if(user()['role']==='patient'&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['checkin'])){$q=$pdo->prepare("INSERT INTO checkins(appointment_id,patient_id,notes) SELECT id,patient_id,? FROM appointments WHERE id=? AND patient_id=? AND status='confirmed'");$q->execute([trim($_POST['notes']??''),(int)$_POST['checkin'],user()['id']]);flash('Check-in details submitted.');go('dashboard.php');}
if(user()['role']==='patient'){$q=$pdo->prepare("SELECT a.*,u.name doctor_name,d.specialty,h.name hospital_name FROM appointments a JOIN doctors d ON d.id=a.doctor_id JOIN users u ON u.id=d.user_id JOIN hospitals h ON h.id=d.hospital_id WHERE a.patient_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC");$q->execute([user()['id']]);$rows=$q->fetchAll();}
$title='Dashboard';require 'includes/header.php';?>
<div class="intro"><span class="tag">PERSONAL DASHBOARD</span><h1>Hello, <?=e(user()['name'])?>.</h1><p>Manage your appointments and personal details.</p><?php if(user()['role']==='patient'):?><a class="btn" href="doctors.php">Find a doctor</a><?php endif;?></div>
<?php if(user()['role']==='patient'):?><section class="panel"><h2>Appointment history</h2><div class="tablewrap"><table><tr><th>Doctor / specialty</th><th>Hospital</th><th>Date / time</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $a):?><tr><td>Dr. <?=e($a['doctor_name'])?><br><?=e($a['specialty'])?></td><td><?=e($a['hospital_name'])?></td><td><?=e($a['appointment_date'])?><br><?=e(substr($a['appointment_time'],0,5))?></td><td><span class="state"><?=e($a['status'])?></span></td><td><?php if(in_array($a['status'],['pending','confirmed'])&&$a['appointment_date']>=date('Y-m-d')):?><form method="post"><?=csrf()?><button class="link danger" name="cancel" value="<?=$a['id']?>">Cancel</button></form><?php endif;?><?php if($a['status']==='confirmed'):?><details><summary>Check-in form</summary><form method="post"><?=csrf()?><input type="hidden" name="checkin" value="<?=$a['id']?>"><textarea name="notes" placeholder="Optional check-in note" maxlength="500"></textarea><button class="btn small">Submit check-in</button></form></details><?php endif;?><?php if($a['status']==='completed'):?><form method="post" action="review.php"><input type="hidden" name="appointment_id" value="<?=$a['id']?>"><button class="link">Write review</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h2>My check-in records</h2><?php $q=$pdo->prepare("SELECT c.*,a.appointment_date FROM checkins c JOIN appointments a ON a.id=c.appointment_id WHERE c.patient_id=? ORDER BY c.created_at DESC");$q->execute([user()['id']]);foreach($q->fetchAll() as $c):?><p><?=e($c['appointment_date'])?> — <?=e($c['notes'])?></p><?php endforeach;?></section><section class="panel"><h2>Personal details</h2><p><?=e(user()['name'])?> · <?=e(user()['email'])?></p><a href="profile.php">Update personal details →</a></section>
<?php else:?><section class="panel"><h2>Hospital account</h2><p>You can manage your hospital profile, doctors and appointment queue.</p><a class="btn" href="manage.php">Open management</a></section><?php endif;?>
<?php require 'includes/footer.php';?>